<style>.eo{padding:22px 30px}.eo-head{display:flex;justify-content:space-between;align-items:center}.eo-card{margin-top:20px;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden}.eo table{width:100%;border-collapse:collapse}.eo th{background:#f7f9fc;color:#718096;text-transform:uppercase;font-size:12px;text-align:left;padding:12px}.eo td{padding:13px 12px;border-top:1px solid #edf1f5}.tag{border-radius:20px;padding:4px 9px;font-size:12px;font-weight:700;background:#fff3bf;color:#9a6700}.tag.paid{background:#dff7ec;color:#087f5b}.back{border:1px solid #d7e0ed;border-radius:8px;padding:9px 14px;text-decoration:none}</style>
<div class="eo"><div class="eo-head"><div><div class="text-primary">Events / Registrations</div><h1 class="h2 mb-1">{{$event->title}}</h1><span class="text-muted">{{$orders->total()}} orders · {{$event->confirmed_seats}} seats reserved</span></div><a class="back" href="{{route('admin.events.index')}}">Back to events</a></div><div class="eo-card table-responsive"><table><thead><tr><th>Order</th><th>Customer & company</th><th>Seats</th><th>Items</th><th>Amount</th><th>Payment</th><th>Date</th></tr></thead><tbody>@forelse($orders as $order)<tr><td><b>{{$order->order_number}}</b></td><td><b>{{$order->customer_name}}</b><br><small>{{$order->company_name}}@if($order->gst_number) · GST: {{$order->gst_number}}@endif</small><br><small>{{$order->customer_email}} · {{$order->customer_phone}}</small></td><td>{{$order->seat_count}}</td><td>@foreach($order->items as $item)<div>{{$item->quantity}} × {{$item->name}}</div>@endforeach</td><td>{{$order->currency}} {{number_format((float)$order->total_amount,2)}}</td><td><span class="tag {{$order->status}}">{{ucfirst($order->status)}}</span>@if($order->payment_reference)<br><small>{{$order->payment_reference}}</small>@endif</td><td>{{$order->created_at->format('d M Y, h:i A')}}</td></tr>@empty<tr><td colspan="7" class="text-center p-5 text-muted">No registrations yet.</td></tr>@endforelse</tbody></table></div><div class="mt-3">{{$orders->links()}}</div></div>
